    starter: 'stillPriced :: [(String, Maybe Int)] -> [String]\n',
    solution: 'stillPriced :: [(String, Maybe Int)] -> [String]\nstillPriced items = map fst (filter (\\(_, price) -> price /= Nothing) items)\n',
